sys_transform_script.script:
(function runTransformScript(source, map, log, target) {
    // The customer side never accepts brand-new incidents from the vendor
    if (action == 'insert' && source.getValue('source_instance') == 'vendor') {
        ignore = true;
        return;
    }
    // Vendor side: route new incidents to its support queue
    if (action == 'insert') {
        target.assignment_group.setDisplayValue('Vendor Support L2');
    }
})(source, map, log, target);
